import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Return how many items of xs were accepted by a bounded queue.

    A queue with capacity `cap` is created empty. Each element of xs is
    offered with a non-blocking put. Every accepted put increments the
    count. The first rejected put (queue full) stops the loop, and the
    count is returned. Nothing is removed from the queue during this.
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_accepted_all_fit() -> None:
    assert accepted(3, [1, 2]) == 2


def test_accepted_empty_input() -> None:
    assert accepted(2, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_exact_capacity() -> None:
    assert accepted(2, [7, 8]) == 2
